import { chromium } from 'playwright';

const url = process.argv[2] || 'http://localhost:5174/?device=wasm&dtype=q8';
const label = process.argv[3] || 'run';

const browser = await chromium.launch({
  args: ['--enable-unsafe-webgpu', '--enable-features=Vulkan'],
});
const page = await browser.newPage();
page.on('console', (msg) => console.log(`  [console] ${msg.text()}`));
page.on('pageerror', (err) => console.log(`  [pageerror] ${err}`));

console.log(`\n=== ${label}: ${url} ===`);
const t0 = Date.now();
await page.goto(url);
await page.waitForFunction('window.__SPIKE_DONE__ === true', { timeout: 180000 }).catch(() => {
  console.log('  [timeout] spike did not finish in time');
});
const wallMs = Date.now() - t0;
const results = await page.evaluate('window.__SPIKE_RESULTS__');
console.log(`  wallClockMs=${wallMs}`);
console.log(JSON.stringify(results, null, 2));

await browser.close();

