const { chromium } = require('playwright');
(async () => {
  const ctx = await chromium.launchPersistentContext('/tmp/pw-profile-webgpu', { args: ['--enable-unsafe-webgpu'] });
  const page = await ctx.newPage();
  await page.goto('http://localhost:5174/?device=webgpu&dtype=fp32');
  await page.waitForTimeout(1000);
  const info = await page.evaluate(async () => {
    const adapter = await navigator.gpu.requestAdapter();
    return { info: adapter?.info, isFallback: adapter?.isFallbackAdapter, limits: adapter?.limits?.maxBufferSize };
  });
  console.log(JSON.stringify(info, null, 2));
  await ctx.close();
})();
